import { NextResponse } from "next/server";
import axios from "axios";

export type CategoryNode = {
  id: number;
  name: string;
  children?: CategoryNode[];
};

export async function GET() {
  const baseUrl =
    process.env.CATALOG_BASE_URL ??
    process.env.BACKEND_BASE_URL ??
    "http://localhost:9090";
  const url = `${baseUrl}/category/tree`;

  try {
    const res = await axios.get<CategoryNode[]>(url, {
      validateStatus: () => true,
      timeout: 10000,
    });

    if (res.status < 200 || res.status >= 300) {
      console.error(
        "Category tree API error:",
        res.status,
        res.statusText,
        url,
      );
      return NextResponse.json<CategoryNode[]>([], { status: 200 });
    }

    const data = res.data;
    if (!Array.isArray(data)) {
      console.error("Category tree: response is not an array", url);
      return NextResponse.json<CategoryNode[]>([], { status: 200 });
    }

    return NextResponse.json<CategoryNode[]>(data);
  } catch (error) {
    console.error("Failed to fetch category tree from", url, error);
    return NextResponse.json<CategoryNode[]>([], { status: 200 });
  }
}
